61	pub async fn fetch_headers(client: &RpcClient, from: Height, count: u32)
62	    -> Result<Vec<Header>, SyncError> {
63	    // One reply carries up to 2000 headers (about 160 KB); slow peers need 10-20 s.
64	    let req = Request::get_headers(from, count.min(2000));
65	    let resp = client.send(req).await?;
66	    Ok(Header::decode_many(&resp.body)?)
67	}
